BEGIN;
INSERT INTO public.protocolos_classificacao (codigo, fonte)
VALUES ('sms-aparecida-2025', 'Protocolo de Classificação de Risco (baseado no protocolo Manchester) · SMS Aparecida de Goiânia · 2025')
ON CONFLICT (codigo) DO UPDATE SET fonte = EXCLUDED.fonte;

DELETE FROM public.protocolo_fluxogramas
 WHERE protocolo_id = (SELECT id FROM public.protocolos_classificacao WHERE codigo = 'sms-aparecida-2025');

INSERT INTO public.protocolo_fluxogramas (protocolo_id, ordem, nome, publico, inclui, discriminadores)
SELECT (SELECT id FROM public.protocolos_classificacao WHERE codigo = 'sms-aparecida-2025'), v.*
FROM (VALUES
  (1, 'Alterações cutâneas', 'adulto', 'feridas; abcessos, afecções da pele, erupções e vesículas disseminadas', '{"vermelho":[["Sinais de choque","hipotensão e/ou bradicardia, palidez, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["Edema de face","inchaço envolvendo a derme profunda e tecido subcutâneo. Representando um edema localizado. O angiodema frequentemente ocorre na face, língua e laringe."],["Perfusão comprometida","TEC > 2 seg com sinais de cianose."],["Dor intensa (7-10/10)",""],["Mordedura (humana ou animal)","Acidentes graves: Ferimentos na cabeça, face, pescoço, mão, polpa digital e/ou planta do pé. Ferimentos profundos, múltiplos ou extensos, em qualquer região do corpo."],["Ferida com sangramento incontrolável","Lesão com sangramento que mesmo após compressão persiste com sangramento visível."],["Acidente com animal peçonhento com sinais e sintomas locais","Acidente ofídico, escorpiônico ou aracnídeo sem toxemia."],["Toxemiado, prostrado ou febril","Cianótico, taquicardíaco, dispneico."],["Contato com produtos químicos de alta letalidade","capacidade de um produto causar um efeito prejudicial após uma única exposição, em um período de tempo curto."]],"amarelo":[["Dor moderada (4-6/10)",""],["Ferida com sangramento controlado",""],["Ferida corto contusa","necessidade de sutura."],["Violência, maus tratos, LESÃO AUTO PROVOCADA",""]],"verde":[["Mordedura (humana ou animal)","Acidentes leves, ferimentos superficiais pouco extensos, geralmente únicos, em tronco e membros (exceto mãos, polpas digitais e planta dos pés). Podem acontecer em decorrência de mordeduras ou arranhaduras, causadas por unha ou dente."],["Dor leve (1-3/10)",""],["Ferida infectada",""],["Ferida superficial",""],["Miíase com infestação intensa",""],["Ferida com necrose",""],["Abscesso","resultado de uma quebra na barreira da pele com contaminação bacteriana."],["Placas eritematosas de início súbito","rubor na pele ocasionado pela vasodilatação capilar associado ou não a exposição solar, processos infecciosos ou inflamatórios, uso de substâncias medicamentosas, processos alérgicos. Quando pressionado embranquece, reaparecendo após cessar a pressão."],["Infecção secundária","presença de sinais flogísticos (dor, calor e rubor)."],["Erupções secretantes ou bolhosas associado a prurido centímetro",""]],"azul":[["Quadro crônico ou recorrente","sem sinais sistêmicos."],["Úlceras crônicas sem repercussão sistêmica",""],["Dor leve > 7 dias",""]]}'::jsonb),
  (2, 'Alterações de comportamento', 'adulto', 'Confusão mental, ansiedade, excitação, letargia, obnubilação; História de ingestão de álcool e drogas', '{"vermelho":[["Sinais de choque","hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["História de overdose ou envenenamento","dosagem excessiva de medicamentos e/ou outras substâncias."],["Extrema agitação / alucinações","Inquietação, aumento da excitabilidade psiquíca, resposta exacerbada a estímulos, atividade motora e verbal inadequada e repetitiva, podendo cursar com agressividade."],["Déficit neurológico agudo","paresia, plegia, disfagia, afasia, ataxia, paralisia facial associado a alterações relevantes dos sinais vitais."]],"amarelo":[["Vômito persistente","assistido na unidade"],["Ataque de pânico",""],["Alto Risco de auto ou heteroagressão",""],["Alucinações ou desorientação",""],["História de inconsciência","perda da capacidade de permanecer alerta."],["Relato de ingestão medicamentosa há mais de 12 horas, sem alteração de comportamento e sem alterações de sinais vitais",""],["Alteração súbita de consciência",""],["Potencial suicida / homicida","ideação suicida, intenção ou planos suicidas ou homicidas."]],"verde":[["Vômitos esparsos",""],["Pensamentos suicidas",""],["História psiquiátrica importante",""],["Moderado risco de auto ou heteroagressão",""]],"azul":[["Sintomas ansiosos","apreensão, preocupação excessivas, dores musculares a mais de 7 dias, fadiga, irritabilidade, ansiedade e dificuldade para dormir."],["Sintomas depressivos","tristeza, choro, apatia, angústia, desespero, fadiga, desanimo, insônia, hipersonia, perda ou aumento do apetite, diminuição da libido, ideias pessimistas de arrependimento ou culpa, problema de concentração e memória."]]}'::jsonb),
  (3, 'Alterações odontológicas', 'adulto', NULL, '{"vermelho":[["Suspeita de septicemia",""],["Traumatismos graves",""],["Choque anafilático",""],["Obstrução das vias aéreas",""],["Sangramento intenso incontrolável",""]],"laranja":[["Dor intensa (7-10/10)",""],["Sangramento médio incontrolável",""],["Erupção ou vesículas disseminadas",""],["Trismo (limitação da abertura bucal)",""],["Periconarites, alveolites e pulpites",""],["Avulsão dentária aguda","< 2 horas."],["Enfartamento ganglionar",""],["Dor mandibular sem queixa dentária",""]],"amarelo":[["Dor moderada (escala de 4 a 6)",""],["Sangramento médico controlável",""],["Edema facial ou de língua",""],["Abcessos dentários",""],["Avulsão dentária aguda ( sem a presença do dente para reimplante)",""]],"verde":[["Dor leve (< 7 dias","Escala de dor 1 a 4)."],["Sangramento pequeno controlável",""],["Febrícola (37,5 °C a 38.4°C)",""],["Sangramento gengival",""],["Sensibilidade da face alterada",""],["Traumatismo dentário ou lesão bucal",""]],"azul":[["Dor leve ( < 7 dias","Escala de dor 1 a 3)."]]}'::jsonb),
  (4, 'Alterações otorrinolaringológicas', 'adulto', NULL, '{"vermelho":[["Respiração ausente",""],["Obstrução de vias aéreas (gaspeando)",""],["Alteração súbita de consciência (escala de Glasgow < 8)",""],["Sangramento intenso incontrolável",""],["Dispneia aguda ou respiração alterada",""]],"laranja":[["Sinais de sepse",""],["Alteração súbita da consciência (escala de Glasgow 9 a 12)",""],["Sangramento médio incontrolável",""]],"amarelo":[["História de trauma",""],["Alteração súbita da consciência (escala de Glasgow 12 a 14)",""],["Corpo estranho em via aérea superior (em nariz ou preso garganta)",""]],"verde":[["Dor e/ou calor e/ou rubor e/ou eritema e/ou edema com ou sem presença de Secreção",""],["Vertigem",""],["Sensibilidade da face alterada ou deformidade",""],["Edema na face",""],["Dor de garganta",""],["Sensação ou relato de corpo estranho no ouvido ou deglutido",""],["Perda e diminuição da audição",""]],"azul":[["Dor > 7 dias",""]]}'::jsonb),
  (5, 'Alterações vasculares', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","Início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de lábio."],["Sinais de choque","Hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência"],["Cianose central",""],["Penetração de projétil ou arma branca em tórax e abdome",""]],"laranja":[["Dor intensa (7-10/10)",""],["Grave mecanismo de trauma","desaceleração frontal rápida; desaceleração vertical rápida."]],"amarelo":[["Dor moderada (4-6/10)","Dor suportável, mas intensa."],["Membros inferiores com cianose",""]],"verde":[["Dor leve (1-3/10)",""],["Edema articular sem flogose","flogose é uma resposta do organismo ao agente agressor, caracterizado pela saída de líquidos e de células do sangue para o interstício."],["Evento recente","Aparecimento < 7 dias."],["Sinais flogísticos locais não articulares","edema, hiperemia, calor e rubor."],["Comprometimento vascular distal",""],["Limitação dos movimentos/função",""]],"azul":[["Dor crônica não agudizada",""],["Úlcera crônica sem repercussão sistêmica",""],["Limitação leve dos movimentos sem perda da função",""]]}'::jsonb),
  (6, 'Convulsão', 'adulto', NULL, '{"vermelho":[["Convulsão ativa","Contratura muscular involuntária de todo o corpo ou de parte dele;"],["Comprometimento/obstrução de vias aéreas","Início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua."]],"laranja":[["Alteração súbita da consciência;",""],["História de overdose ou envenenamento","dosagem excessiva de medicamentos e/ou outras substâncias;"],["Respiração inadequada","incapacidade de falar; cianose; letargia e/ou confusão mental."],["Sinais neurológicos focais","paresia, parestesia, disfasia, afasia, ataxia, distúrbio do equilíbrio."],["Crise convulsiva reentrante","crise repetida sem a recuperação completa da consciência entre elas;"],["Hipoglicemia < 70 mg/dl",""],["Em pós","ictal- momento posterior a crise convulsiva que pode se caracterizar por perda da consciência, confusão ou desorientação mental e letargia."]],"amarelo":[["Crise convulsiva há menos de 12h e alerta","relato de crise convulsiva nas últimas 12 horas."],["Crise convulsiva há menos de 12h e alerta","relato de crise convulsiva nas últimas 12 horas."],["História de Trauma craniano recente","TCE < 7 dias."]],"verde":[["Cefaleia com história de convulsão < 7 dias",""],["Crise convulsiva < 7 dias",""]],"azul":[["Crise convulsiva isolada > 7 dias sem demais sintomas",""]]}'::jsonb),
  (7, 'Dengue', 'adulto', NULL, '{"vermelho":[["Sinais de choque","hipotensão e/ou bradicardia, palidez, sudorese, pele fria, pulso fino, perfusão diminuída, alteração do nível de consciência. Choque- evidenciado por taquicardia; extremidades distais frias; TEC> 2segundos); pressão arterial convergente (< 20 mm Hg); taquipneia; oliguria (< 1,5 ml/kg/h)."],["Sangramentos ativos não controláveis",""],["Hipotensão severa","PAS < 90 mmHg ou PAM < 70 mmHg ou diminuição da PAS> 40 mmHg."],["Cianose",""]],"laranja":[["Hipotensão","redução na PAS ≥ 20 mmHg ou na PAD ≥ 10 mmHg."],["Bradicardia< 60 bpm",""],["Pressão convergente","diferença entre a pressão sistólica e diastólica < 20mmhg."],["Plaquetas < 50.000/mm3",""]],"amarelo":[["Dor abdominal intensa (referida ou à palpação) e contínua",""],["Vômitos persistentes",""],["Acúmulo de líquidos (ascite, derrame pleural, derrame pericárdico)",""],["Hepatomegalia maior do que 2 cm abaixo do rebordo costal",""],["Sangramento de mucosa",""],["Letargia e/ou irritabilidade",""],["Aumento progressivo do hematócrito",""]],"verde":[["Dengue SEM sinais de alarme, com condição especial, ou com risco social e com comorbidades: lactentes (< 2 anos), gestantes, adultos com idade acima de 65 anos, hipertensão arterial ou outras doenças cardiovasculares graves, diabetes mellitus, doença pulmonar obstrutiva crônica (DPOC), asma, obesidade, doenças hematológicas crônicas (principalmente anemia falciforme e púrpuras), doença renal crônica, doença ácido péptica, hepatopatias e doenças autoimunes",""]],"azul":[["Dengue sem sinais de alarme, sem condição especial, sem risco social e sem comorbidades",""]]}'::jsonb),
  (8, 'Desmaio, vertigem', 'adulto', NULL, '{"vermelho":[["Alteração do nível de consciência","Escala de Coma de Glasgow <8."],["Comprometimento/obstrução de vias aéreas","Início súbito de grave dificuldade respiratória, sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho, edema de língua."],["Convulsionando",""],["Sinais de choque","palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["Dor torácica","dor intensa em aperto ou peso no meio do peito, irradiando para o braço esquerdo ou pescoço. Pode-se associar sudorese, náuseas e epigastralgia."],["Dispneia aguda","fôlego curto ou falta de ar súbita associada a baixa saturação."],["Déficit neurológico agudo","perda de função neurológica nas últimas 24 horas (paresia, plegia, disfagia, afasia, ataxia, paralisia facial)."],["Pulso anormal (filiforme)","Tipo de pulso arterial muito fraco."],["Dor intensa (7-10/10)","Dor intolerável, geralmente descrita como jamais sentida."],["História importante de alergia","sensibilidade conhecida com reação grave ( ex.: picada de abelha)."],["Hipoglicemia","glicemia <70 mg/dl."]],"amarelo":[["História de trauma craniano RECENTE",""],["História de inconsciência nas últimas 12 horas",""],["História discordante","Quando a história fornecida não explica os achados físicos. Pode ser um marcador de lesão não acidental em crianças ou adultos vulneráveis, podendo ser sentinela de abuso e maus tratos."],["Relato de primeira crise convulsiva",""],["Dor moderada (4-6/10)","Dor suportável, mas intensa."],["Déficit neurológico agudo","perda de função neurológica nas últimas 24 horas (paresia, plegia, disfagia, afasia, ataxia, paralisia facial)."]],"verde":[["Dor leve (1-3/10)",""],["Vômitos esparços",""],["Evento de início < 6 horas",""]],"azul":[["Vertigem > 7 dias",""]]}'::jsonb),
  (9, 'Diarreia e vômitos', 'adulto', NULL, '{"vermelho":[["Sinais de choque","Palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["Dor intensa (7-10/10)","Dor intolerável."],["Presença de grande quantidade de sangue no vômito",""],["Evacuação de sangue vivo ou escurecido presenciada",""],["Respiração inadequada","incapacidade de falar; cianose; letargia e/ou confusão mental."]],"amarelo":[["Relato de fezes pretas ou em groselha",""],["Relato agudo de hematêmese",""],["Sinais de desidratação","muita sede, boca seca, olhos encovados, vômitos frequentes, sem urinar nas últimas 12h, prega cutânea se desfaz lentamente (< 10 seg), pulso fino e rápido, perfusão periférica lenta (3 a 5 seg)."]],"verde":[["Dor leve (1-3/10)",""],["Vômitos esparços",""],["Evento de início < 6 horas",""],["Febril",""]],"azul":[["Busca de reavaliação sem queixas",""],["Último evento> 7 dias",""]]}'::jsonb),
  (10, 'Dor abdominal', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas",""],["Sinais de choque","palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência"]],"laranja":[["Hematêmese",""],["Evacuação de sangue vivo ou escurecido",""],["Dor intensa (7-10/10) -dor intolerável",""],["Respiração inadequada","cianose associada a baixa saturação; letargia e/ou confusão mental."]],"amarelo":[["Relato de fezes pretas ou em groselha",""],["Dor moderada (4-6/10)",""],["Relato agudo de hematêmese",""],["Vômitos persistentes","no mínimo 3 eventos nas últimas 24 horas."]],"verde":[["Dor leve (1-3/10)",""],["Vômitos",""],["Evento recente< 7 dias",""]],"azul":[["Dor > 7 dias",""]]}'::jsonb),
  (11, 'Dor cervical', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua,"],["Sinais de choque","Hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["Dor intensa (7-10/10)",""]],"amarelo":[["Déficit neurológico novo","perda de função neurológica, alteração ou perda de sensibilidade, fraqueza de membros, retenção urinária ou alteração há mais de 24 hs."],["Dor moderada (4-6/10)",""],["Trauma direto no pescoço","traumatismos de garganta, nuca e região supraclavicular."]],"verde":[["Dor leve (1-3/10)",""],["Evento de início < 7 dias",""]],"azul":[["Dor > 7 dias",""]]}'::jsonb),
  (12, 'Dor de cabeça', 'adulto', NULL, '{"vermelho":[["Convulsão ativa",""],["Sinais de choque","hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."]],"laranja":[["Dor intensa (7-10/10)",""],["Estado mental alterado","desorientado no tempo, lugar e desconhecimento de pessoas; Incapacidade de cumprir ordens simples; pensamento desconexos; letargia e/ou confusão mental."],["Sinais neurológicos focais agudo (menor que 24 horas)","paresia, parestesia, disfasia, afasia, ataxia, distúrbio do equilíbrio."],["Perda aguda completa da visão",""],["Desvio agudo de rima labial",""]],"amarelo":[["História de inconsciência","Perda da capacidade de permanecer alerta."],["Dor moderada (4-6/10)","Dor suportável, mas intensa."]],"verde":[["Evento recente < 7 dias",""],["Dor leve (1-3/10)",""]],"azul":[["Dor > 7 dias",""]]}'::jsonb),
  (13, 'Dor de garganta', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","início súbito de grave dificuldade respiratória sem febre ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua."]],"laranja":[["Dor intensa (7-10/10)",""]],"amarelo":[["Dor moderada (4-6/10)","Dor suportável, mas intensa."],["Febre",""]],"verde":[["Dificuldade para deglutir",""],["Tosse seca ou produtiva e coriza",""],["Dor leve (1-3/10)",""],["Evento recente < 7 dias",""],["Febril",""]],"azul":[["Dor > 7 dias",""]]}'::jsonb),
  (14, 'Dor na coluna', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","Início súbito de grave dificuldade respiratória sem febr ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua"],["Sinais de choque","hipotensão ou bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."],["Penetração de projétil por arma de fogo",""]],"laranja":[["Dor intensa (7-10/10) -dor intolerável",""],["Grave mecanismo de trauma","desaceleração frontal rápida; desaceleração vertical rápida e/ou deformidade aguda."]],"amarelo":[["Dor moderada (4-6/10)","dor suportável, mas intensa."],["Dificuldade de andar",""],["Limitação dos movimentos/função",""],["Mecanismo trauma","desaceleração frontal rápida; desaceleração vertical rápida."]],"verde":[["Dor leve (1-3/10)","dor suportável."],["Evento recente","aparecimento < 7 dias."]],"azul":[["Dor crônica",""]]}'::jsonb),
  (15, 'Dor torácica', 'adulto', NULL, '{"vermelho":[["Sinais de choque","hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."],["Trauma penetrante por arma branca e/ou fogo",""]],"laranja":[["Dor intensa (7-10/10)",""],["Dor precordial","Dor intensa em aperto ou peso no meio do peito, irradiando para o braço esquerdo, pescoço ou mandíbula. Pode-se associar ou não a sudorese, náuseas e vômitos. Dor intolerável."],["Dispneia aguda","fôlego curto ou falta de ar súbita ou repentina piora de falta de ar crônica associada a baixa saturação e/ou uso de musculatura acessória."],["Trauma torácico com falta de ar associado a baixa saturação e/ou uso de musculatura acessória",""]],"amarelo":[["Dor moderada (4-6/10)","dor suportável, mas intensa."]],"verde":[["Dor leve (1-3/10)","Dor suportável."],["Evento recente",""],["Dor pleurítica","dor em fincada localizada no peito que piora com respiração, tosse e ou espirro."]],"azul":[["Evento> 7 dias",""],["Retorno sem queixas para reavaliação Clínica",""]]}'::jsonb),
  (16, 'Intoxicações exógenas', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","Início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua."],["Convulsionando",""],["Sinais de choque","Hipotensão (PA sistólica ≤ 80mmHg), Taquicardia (FC ≥ 140bpm) ou Bradicardia (FC ≤ 40bpm), palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída,, alteração do nível de consciência; Letargia e/ou confusão mental; Cianose."]],"laranja":[["Edema facial",""],["Edema de língua",""],["Dor intensa (7-10/10)",""],["Saturação de oxigênio < 92% em ar ambiente",""],["Alteração súbita da consciência",""],["Acidente pérfuro","cortante com material biológico."],["Lesão ocular química",""]],"amarelo":[["Erupção ou vesículas disseminadas",""],["História de crise convulsiva após intoxicação",""],["Dor moderada (4-6/10",""]],"verde":[["Dor leve recente",""],["Evento recente",""],["Alterações dérmicas locais",""]],"azul":[["Evento> 7 dias",""]]}'::jsonb),
  (17, 'Mal-estar geral', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","Início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua."],["Sinais de choque","Hipotensão (PA sistólica ≤ 80mmHg), Taquicardia (FC ≥ 140bpm) ou Bradicardia (FC ≤ 40bpm), palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída, irritabilidade, alteração do nível de consciência e oligúria; Letargia e/ou confusão mental e cianose."],["Convulsionando",""]],"laranja":[["Alteração súbita da consciência",""],["Déficit neurológico agudo","qualquer perda de função neurológica que ocorreu nas últimas 24 hs: alteração ou perda de sensibilidade e retenção urinária."],["Hipoglicemia","glicemia < 70 mg/dl."]],"amarelo":[["História de Hemoptise",""],["Erupção de vesículas disseminadas","erupção secretante ou bolhosa cobrindo 10% da superfície corporal."],["Dor moderada (4-6/10)",""],["Febre",""]],"verde":[["Dor leve recente (1-3/10)",""],["Febril",""],["História de viagem recente para regiões endêmicas","intervalo< 7 dias."],["Imunossupressão conhecida","qualquer paciente em uso de drogas imunossupressoras (incluindo uso de corticoide prolongado) ou que seja HIV positivo."],["História hematológica importante",""],["Púrpura","erupção de qualquer parte do corpo que é causada por pequenas hemorragias debaixo da pele."]],"azul":[["Dor > acima de 7 dias",""]]}'::jsonb),
  (18, 'Mordeduras, picadas e acidentes com animais peçonhentos', 'adulto', NULL, '{"vermelho":[["Obstrução de vias aéreas","Início súbito de grave dificuldade respiratória ou sintomas respiratórios prévios, presença de secreção, sangue, corpo estranho e edema de língua."],["Hemorragia não controlável",""],["Sinais choque","Hipotensão ou Bradicardia, palidez acentuada, sudorese, pele fria, pulso fino, perfusão diminuída e alteração do nível de consciência."],["Mutilação","amputação ou perda de partes corporais por mordedura humana ou animal com sangramento INCONTROLÁVEL."]],"laranja":[["Edema facial",""],["Edema de língua",""],["Hemorragia",""],["Refere alergia importante","sensibilidade conhecida com reação grave (p. ex nozes, camarão, picada de abelha)."],["Ferimento extenso por mordedura ou em áreas críticas","ferimentos de segmento cefálico, mãos e pés."],["Alteração súbita da consciência",""],["Sat O2 muita baixa","Saturação de oxigênio < 92% em ar ambiente."],["Mutilação","amputação ou perda de partes corporais por mordedura humana ou animal com sangramento controlável."],["Dor intensa",""]],"amarelo":[["Erupção ou vesículas disseminadas","vesículas ou bolhas distintas ou confluentes que alcançam mais de 10% da superfície corporal por meio da regra dos nove de Wallace; a qual estima 9% de superfície corporal para cada uma das regiões a seguir: cabeça e pescoço, cada membro, cada quadrante do tronco, cada coxa, cada perna e pé; prurido, envolvendo mais de uma região corporal."],["Dor modedrada (4-6/10)",""],["Coceira intensa",""]],"verde":[["Infecção local","manifesta-se geralmente com inflamação (dor, inchaço e vermelhidão) restrita a uma área definida, com ou sem coleção de pus."],["Inflamação local","implica em dor, inchaço e vermelhidão restrita a uma área definida."],["Dor leve recente (1-3/10)",""],["Evento recente",""]],"azul":[["Evento> 7 dias",""]]}'::jsonb),
