  (35, 'Alterações glicêmicas', 'pediatrico', NULL, '{"vermelho":[["Alteração súbita da consciência (escala de Glasgow < 8)",""],["Confusão mental, sonolência, visão turva, distúrbios de marcha",""],["Crise convulsiva (em vigência)",""],["Hipoglicemia (HGT < 45 mg/dl em RN ou < 60mg/dl em > 1 mês)",""],["Paciente diabético com alterações sistêmicas","hipoglicemia (HGT < 50 mg/dl) ou Hiperglicemia (HGT > 300 mg/dl), com sonolência; vômitos; dor abdominal e desidratação grave."],["Choque séptico",""]],"laranja":[["Sinais de sepse",""],["Alteração súbita da consciência (escala de Glasgow 9 a 12)",""],["Crise convulsiva referida (HGT > 400 mg/dl)",""],["Sudorese intensa com pele fria/ pegajosa/ hálito cetônico/ apatia/ fadiga/ tontura/ sudorese/ cansaço/ boca seca (HGT > 200 mg\\dl)",""]],"amarelo":[["Alteração súbita da consciência (Escala de glasgow 13 a 14)",""],["Hiperglicemia: HGT entre 200 mg/dl e 350 mg/dl sem nenhum outro sintoma associado",""],["Criança com história de diabetes apresentando um ou mais sintomas: sudorese, alteração do estado mental, visão turva, febre, vômitos, taquipnéia, taquicardia",""],["Paciente diabético com história de crise convulsiva < 12 horas","independente do valor do HGT."]],"verde":[["Hiperglicemia sem nenhuma outra alteração","HGT > 200mg/dl."]],"azul":[["Paciente diabético com HGT entre 60 mg/dl e 200 mg/dl sem sintomas que caracterizam cetoacidose diabética",""]]}'::jsonb),
